import java.util.*;
class Pair{int val,idx; Pair(int v,int i){val=v;idx=i;}}
public class Solution{
 public static void main(String[] args){
  Scanner sc=new Scanner(System.in);
  int n=sc.nextInt();
  Pair[] arr=new Pair[n];
  for(int i=0;i<n;i++) arr[i]=new Pair(sc.nextInt(),i);
  Arrays.sort(arr,(a,b)->a.val-b.val);
  boolean[] vis=new boolean[n];
  int ans=0;
  for(int i=0;i<n;i++){
   if(vis[i]||arr[i].idx==i) continue;
   int cycle=0,j=i;
   while(!vis[j]){
    vis[j]=true;
    j=arr[j].idx;
    cycle++;
   }
   ans+=cycle-1;
  }
  System.out.println(ans);
 }
}

